"""Publish the checked floor joins and source basement enclosure."""
from pathlib import Path
import json,hashlib,shutil,sys,re
ROOT=Path(__file__).resolve().parents[1]
WORK=Path('/Users/finbarr/.codex/worktrees/performance-audit/kyoto/.local/station-realism')
assembly,wall,native,wallnative=sys.argv[1:]
OUT=ROOT/'notes/hall-basement-enclosure';OUT.mkdir(exist_ok=True)
load=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
a=load(WORK/assembly/'report.json');n=load(WORK/native/'report.json');wn=load(WORK/wallnative/'report.json');w=load(WORK/wall/'report.json')
assert n['summary']['pass'] and n['nativeSha256']==a['outputs']['nativePanelsSha256']
assert not wn['failures'] and wn['nativePanelsSha256']==w['outputs']['nativePanelsSha256']
assert load(WORK/'hall-descents-assembly-12/floor-joins-proof.json')['pass']
files={'before.png':ROOT/'notes/hall-bank-profiles/after.png','after.png':WORK/assembly/'close/source.png','basement.png':WORK/assembly/'basement/source.png','assembly.json':WORK/assembly/'report.json','enclosure.json':WORK/wall/'report.json','source-proof.json':WORK/wall/'source-proof.json','native.json':WORK/native/'report.json','wall-native.json':WORK/wallnative/'report.json','floor-native.json':WORK/'central-hall-bay-native-12/report.json','floor-joins-proof.json':WORK/'hall-descents-assembly-12/floor-joins-proof.json','serialization-proof.json':WORK/assembly/'serialization-proof.json','prior-floor-overlap.json':WORK/'hall-descents-11/floor-interface-audit.json','prior-wall-native-failure.json':WORK/'hall-well-lining-native-01/report.json','second-wall-native-failure.json':WORK/'hall-well-lining-native-02/report.json','floor-ownership-failure.json':WORK/wall/'source-proof-failure.json','source-verifier-before-floor-ownership.py':WORK/wall/'source-verifier-before-floor-ownership.py','enclosure-spec.json':WORK/'hall-well-lining-spec-08/spec.json'}
for name,src in files.items():shutil.copyfile(src,OUT/name)
style=re.search(r'<style>(.*?)</style>',(ROOT/'notes/hall-bank-profiles/index.html').read_text(),re.S).group(1)
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Central hall · basement enclosure</title><style>'''+style+'''</style><main><nav><a href="../../index.html">Research library</a><a href="../HALL-BASEMENT-ENCLOSURE.md">Evidence note</a><a href="../hall-bank-profiles/index.html">Previous construction</a></nav><h1>The wells now have<br>source-based walls and soffits.</h1><p>The floor outlines meet the retained landing plates, and the basement enclosure follows the municipal model's curved and stepped profiles. All five floor openings remain.</p><p class="notice"><strong>Uninstalled construction candidate.</strong> Storefronts, signage, ceiling fittings, lighting, material matching and wider public-route connections remain unfinished. Hidden exterior backing closures are explicitly inferred. No final photographic match or full-game performance acceptance is claimed.</p><h2>Same-camera comparison</h2><div class="grid"><figure><a href="before.png"><img src="before.png" alt="Prior source-profile escalators with open surroundings below the upper floor"></a><figcaption>Before: source-profile banks, without well walls.</figcaption></figure><figure><a href="after.png"><img src="after.png" alt="Escalator banks surrounded by the source-shaped well walls and central soffit"></a><figcaption>After: reconciled floor joins and source wall/soffit enclosure. Inspection lighting and camera unchanged.</figcaption></figure></div><h2>From the lower deck</h2><figure><a href="basement.png"><img src="basement.png" alt="Lower-deck inspection view of the enclosed descent and overhead structure"></a><figcaption>Provisional neutral finish and uniform inspection lighting. This view is not registered to a reference photograph.</figcaption></figure><h2>Verified</h2><ul><li>Only the two floor records changed in the parent assembly; 673 other records and all four moving mechanisms remain exact. Three upper openings and two lower holes remain.</li><li>Floor/plate overlap and coverage errors are below the existing 1e−6 m² numerical limit. Floor boundary rounding error is below 0.5 µm.</li><li>318 clipped wall/soffit fragments remain covered after the declared floor alignment; all 16 separate lower-floor faces are also checked. Added faces are limited to horizontal cut caps and the declared hidden exterior backing extensions.</li><li>All 13,764 hall ray probes pass. Final enclosure collision probes and final-assembly checks pass: 324 support/headroom points, 24 through walks and four standing rides.</li><li>Browser/native export agreement passes. The browser asset build passes. Full-station course checks and gameplay performance/soak checks remain open.</li></ul><h2>Retained collision failure</h2><p>Two initial underside-cap triangles produced 2.16 and 3.23 mm native placement errors. Boundary retriangulation fixes those caps. A later 1.76 mm sliver error is resolved by aligning near-level source vertices to the common deck, with a maximum height adjustment of 0.0483 mm. The failed receipt remains available; the 1 mm collision tolerance is unchanged.</p><nav>'''
for file,label in [('assembly.json','Assembly'),('enclosure.json','Enclosure'),('source-proof.json','Source surfaces'),('floor-joins-proof.json','Floor joins'),('serialization-proof.json','Export agreement'),('native.json','Final walks and rides'),('wall-native.json','Enclosure collision'),('floor-native.json','Hall collision'),('prior-wall-native-failure.json','Initial collision failure')]:page+=f'<a href="{file}">{label}</a>'
page+='''</nav><p><small>Kyoto City municipal source geometry: CC BY 4.0. Construction review: 28 September 2026. Full station remains courtyard life04/browser04. No installation or deployment.</small></p></main></html>'''
(OUT/'index.html').write_text(page)
(OUT/'publication-receipt.json').write_text(json.dumps({'files':{name:sha(OUT/name)for name in [*files,'index.html']},'assemblySha256':a['outputs']['glbSha256'],'nativeSummary':n['summary'],'enclosureProbeCount':len(wn['samples']),'fullStationChanged':False,'finalVisualAcceptance':False},indent=2)+'\n')
print(OUT/'index.html')
